 <div class="overlay" id="modal"><div class="modal"><div class="sigil" id="modalSigil">✦</div><div class="result" id="resultLabel">The frontier calls</div><h1 id="modalTitle">A keep against the dark</h1><p id="modalText">The Ashen host has crossed the pass. Gather your company, hold the line, and bring down their stronghold.</p><div class="modal-actions"><button class="primary" id="resumeBtn">Enter the field</button><button class="secondary" id="restartBtn" style="display:none">Play again</button></div></div></div>
 </div>
 <script type="module">
 import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
-</script>
+
+const canvas=document.querySelector('#world');
+const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
+renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight,false);
+renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
+renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.13;
+const scene=new THREE.Scene();scene.background=new THREE.Color('#263b36');scene.fog=new THREE.Fog('#263b36',38,78);
+const camera=new THREE.OrthographicCamera(-19,19,12,-12,.1,120);let camTarget=new THREE.Vector3(0,0,0),zoom=27;
+function positionCamera(){const aspect=innerWidth/innerHeight;const vh=zoom;const vw=vh*aspect;camera.left=-vw/2;camera.right=vw/2;camera.top=vh/2;camera.bottom=-vh/2;camera.position.set(camTarget.x,26+zoom*.34,camTarget.z+zoom*.83);camera.lookAt(camTarget);camera.updateProjectionMatrix()}
+positionCamera();
+scene.add(new THREE.HemisphereLight('#d8e6d1','#39433b',2.05));
+const sun=new THREE.DirectionalLight('#fff0d4',2.4);sun.position.set(-12,25,10);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-35;sun.shadow.camera.right=35;sun.shadow.camera.top=30;sun.shadow.camera.bottom=-30;sun.shadow.bias=-.0002;scene.add(sun);
+const fill=new THREE.DirectionalLight('#86a9ba',.75);fill.position.set(13,10,-15);scene.add(fill);
+const mat=(color,rough=.86,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
+const groundMat=mat('#667253');const ground=new THREE.Mesh(new THREE.PlaneGeometry(64,48),groundMat);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
+const road=new THREE.Mesh(new THREE.PlaneGeometry(34,5.2),mat('#9a8865'));road.rotation.x=-Math.PI/2;road.position.set(0,-.045,0);road.receiveShadow=true;scene.add(road);
+const roadEdge=new THREE.Mesh(new THREE.PlaneGeometry(34,.22),mat('#c4aa7b'));roadEdge.rotation.x=-Math.PI/2;roadEdge.position.set(0,-.032,-2.62);scene.add(roadEdge);
+// Broken paving stones give the central pass a hand-laid, lived-in feel.
+for(let i=0;i<80;i++){const x=-16+Math.random()*32,z=-2.25+Math.random()*4.5;const stone=new THREE.Mesh(new THREE.CircleGeometry(.08+Math.random()*.2,5),mat(Math.random()>.5?'#b7a784':'#746d56'));stone.rotation.x=-Math.PI/2;stone.position.set(x,.012,z);scene.add(stone)}
+// Ground cover and scattered boulders around the pass.
+for(let i=0;i<280;i++){let x=(Math.random()-.5)*53,z=(Math.random()-.5)*37;if(Math.abs(z)<3.2&&Math.abs(x)<18)continue;const r=.025+Math.random()*.09;const tuft=new THREE.Mesh(new THREE.SphereGeometry(r,5,4),mat(Math.random()>.5?'#8b9161':'#465b48'));tuft.scale.set(1,.24,1);tuft.position.set(x,.015,z);tuft.castShadow=true;scene.add(tuft)}
+function makeTree(x,z,scale=1){const g=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13,.21,1.35,7),mat('#564b39'));trunk.position.y=.68;trunk.castShadow=true;g.add(trunk);for(let n=0;n<3;n++){const crown=new THREE.Mesh(new THREE.ConeGeometry(.78-n*.12,1.38,7),mat(['#365346','#42614e','#4b6850'][n]));crown.position.y=1.32+n*.59;crown.castShadow=true;crown.receiveShadow=true;g.add(crown)}g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);return g}
+for(let side of [-1,1]){for(let i=0;i<16;i++){const z=-17+i*2.15+(Math.random()-.5);makeTree(side*(20+Math.random()*5),z,.75+Math.random()*.65)}for(let i=0;i<20;i++){const x=side*(8+Math.random()*13),z=(Math.random()>.5?1:-1)*(5+Math.random()*13);if(Math.abs(x)<10&&Math.abs(z)<7)continue;makeTree(x,z,.55+Math.random()*.65)}}
+function cylinder(radius,height,color,x,y,z,sides=8){const mesh=new THREE.Mesh(new THREE.CylinderGeometry(radius*.82,radius,height,sides),mat(color));mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;return mesh}
+function addRock(x,z,s=1){const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),mat('#76745f'));rock.position.set(x,s*.48,z);rock.scale.set(1,.75,.9);rock.castShadow=true;scene.add(rock)}
+for(const p of [[-6,7,1.1],[4,-9,.8],[-22,6,1.3],[21,-7,1],[9,15,.8],[-8,-15,.9]])addRock(...p);
+// Keep models: layered stone walls, timber towers and warm standards.
+const keepHp={home:100,enemy:100};
+function makeKeep(x,enemy=false){const g=new THREE.Group();const stone=enemy?'#604843':'#626d63',roof=enemy?'#8b5147':'#4d6c6d',trim=enemy?'#d18a69':'#b8a474';
+ const base=new THREE.Mesh(new THREE.BoxGeometry(4.4,2.25,3.8),mat(stone));base.position.y=1.12;base.castShadow=true;base.receiveShadow=true;g.add(base);
+ for(const dx of [-1.65,1.65])for(const dz of [-1.35,1.35]){const tower=cylinder(.58,4.2,stone,dx,2.05,dz,8);g.add(tower);const cap=new THREE.Mesh(new THREE.ConeGeometry(.72,1.25,8),mat(roof));cap.position.set(dx,4.73,dz);cap.castShadow=true;g.add(cap)}
+ const hall=new THREE.Mesh(new THREE.BoxGeometry(2.2,2.35,2),mat(enemy?'#805a4c':'#768576'));hall.position.set(0,2.18,-.25);hall.castShadow=true;g.add(hall);
+ const top=new THREE.Mesh(new THREE.ConeGeometry(1.7,1.4,4),mat(roof));top.position.set(0,4.05,-.25);top.rotation.y=Math.PI/4;top.castShadow=true;g.add(top);
+ const door=new THREE.Mesh(new THREE.BoxGeometry(.8,1.55,.12),mat('#342f2a'));door.position.set(0,.78,1.96);g.add(door);
