const homeKeep=makeKeep(-16,false),enemyKeep=makeKeep(16,true);
const units=[];let selected=null,wood=180,gold=240,supply=3,supplyMax=12,homeIntegrity=100,enemyIntegrity=100,gameOver=false,paused=false,attackOrder=false,toastTimer=0,enemyTimer=19,dayClock=0,lastTime=0;
function makeUnit(side,type,x,z){const g=new THREE.Group(),friendly=side==='ally',elite=type==='vanguard',scout=type==='scout';const cloth=friendly?(scout?'#799d8a':'#3e7180'):(scout?'#9b6150':'#873d3b'),armor=friendly?'#afbea8':'#c3a187',skin='#c69c76',dark=friendly?'#283c3b':'#402a29';
 const body=new THREE.Mesh(new THREE.CylinderGeometry(.34,.45,.82,8),mat(cloth));body.position.y=.76;body.castShadow=true;g.add(body);
 const cape=new THREE.Mesh(new THREE.BoxGeometry(.52,.72,.15),mat(dark));cape.position.set(0,.84,-.3);cape.castShadow=true;g.add(cape);
 const head=new THREE.Mesh(new THREE.SphereGeometry(.25,10,8),mat(skin));head.position.y=1.38;head.castShadow=true;g.add(head);
 const helm=new THREE.Mesh(new THREE.ConeGeometry(.31,.38,6),mat(armor));helm.position.y=1.62;helm.castShadow=true;g.add(helm);
 const shoulder=cylinder(.17,.18,armor,-.39,1.08,0,6);g.add(shoulder);const shoulder2=cylinder(.17,.18,armor,.39,1.08,0,6);g.add(shoulder2);
 const belt=new THREE.Mesh(new THREE.BoxGeometry(.68,.1,.48),mat('#c5a35e'));belt.position.y=.42;g.add(belt);
 // The sword is raised slightly forward and catches the cold light.
 const sword=new THREE.Mesh(new THREE.BoxGeometry(.09,.78,.12),mat(scout?'#c5c6b8':'#d5d4c2',.34,.4));sword.position.set(.5,.91,.08);sword.rotation.z=-.33;sword.castShadow=true;g.add(sword);
 const guard=new THREE.Mesh(new THREE.BoxGeometry(.35,.07,.16),mat('#c49a5d',.5,.3));guard.position.set(.49,.69,.08);guard.rotation.z=-.33;g.add(guard);
 const legs=[];for(const dx of [-.17,.17]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.19,.5,.22),mat(dark));leg.position.set(dx,.22,0);leg.castShadow=true;g.add(leg);legs.push(leg)}
 const ring=new THREE.Mesh(new THREE.RingGeometry(.48,.58,28),new THREE.MeshBasicMaterial({color:friendly?'#b4e3d3':'#ef9b80',transparent:true,opacity:.8,side:THREE.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=.045;ring.visible=false;g.add(ring);
 const shadow=new THREE.Mesh(new THREE.CircleGeometry(.44,16),new THREE.MeshBasicMaterial({color:'#101614',transparent:true,opacity:.3}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.018;g.add(shadow);
 const entity={mesh:g,side,type,x,z,hp:elite?100:(scout?68:82),maxHp:elite?100:(scout?68:82),speed:scout?3.2:2.5,damage:scout?10:13,range:scout?3.1:1.55,attackRate:scout?1.25:1.05,cooldown:Math.random()*.4,dest:null,target:null,ring,legs,walk:Math.random()*5,dead:false};g.position.set(x,0,z);g.userData.entity=entity;g.traverse(o=>{if(o.isMesh)o.userData.entity=entity});scene.add(g);units.push(entity);if(friendly&&!selected)selectUnit(entity);return entity}
function addInitialSquad(){makeUnit('ally','vanguard',-11,-1.3);makeUnit('ally','guard',-11.4,1.15);makeUnit('ally','guard',-9.6,2.1);for(let i=0;i<5;i++)makeUnit('enemy',i===4?'scout':'guard',13+Math.random()*2,(i-2)*1.25)}
function selectUnit(u){if(selected)selected.ring.visible=false;selected=u&&!u.dead?u:null;if(selected){selected.ring.visible=true;document.querySelector('#selectedName').textContent=selected.type==='vanguard'?'Vanguard':selected.type==='scout'?'Ranger':'Northwatch guard';document.querySelector('#selectedMeta').textContent=(selected.side==='ally'?'READY · NORTHWATCH':'HOSTILE · ASHEN HOST');document.querySelector('#portrait').textContent=selected.type==='scout'?'🏹':'♞';document.querySelector('#selectedHp').style.width=`${Math.max(0,selected.hp/selected.maxHp*100)}%`}else{document.querySelector('#selectedName').textContent='No unit selected';document.querySelector('#selectedMeta').textContent='SELECT A COMPANY';document.querySelector('#selectedHp').style.width='0%'}}
function spawn(side,type,x,z){if(side==='ally'){if(supply>=supplyMax){notify('Supply limit reached — build a watchtower to expand your company.');return null}if(type==='scout'&&gold<60){notify('Not enough crowns to train a ranger.');return null}if(type!=='scout'&&gold<80){notify('Not enough crowns to train a guard.');return null}gold-=type==='scout'?60:80;supply++}return makeUnit(side,type,x,z)}
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
addInitialSquad();

