addInitialSquad();
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0),hitPoint=new THREE.Vector3(),pointerMap=new Map();let dragStart=null,pinchStart=null;
function worldAt(clientX,clientY){pointer.x=clientX/innerWidth*2-1;pointer.y=-(clientY/innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);return raycaster.ray.intersectPlane(groundPlane,hitPoint)?hitPoint.clone():null}
function onPointerDown(e){canvas.setPointerCapture?.(e.pointerId);pointerMap.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointerMap.size===2){const a=[...pointerMap.values()];pinchStart={distance:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y),zoom};dragStart=null;return}dragStart={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};}
function onPointerMove(e){if(!pointerMap.has(e.pointerId))return;const old=pointerMap.get(e.pointerId);pointerMap.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointerMap.size===2&&pinchStart){const a=[...pointerMap.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);zoom=THREE.MathUtils.clamp(pinchStart.zoom*pinchStart.distance/Math.max(1,d),16,42);positionCamera();return}if(!dragStart)return;const dx=e.clientX-dragStart.lastX,dy=e.clientY-dragStart.lastY;if(Math.hypot(e.clientX-dragStart.x,e.clientY-dragStart.y)>5)dragStart.moved=true;if(dragStart.moved){const scale=zoom/innerHeight;camTarget.x-=dx*scale;camTarget.z+=dy*scale*1.1;camTarget.x=THREE.MathUtils.clamp(camTarget.x,-14,14);camTarget.z=THREE.MathUtils.clamp(camTarget.z,-8,8);positionCamera()}dragStart.lastX=e.clientX;dragStart.lastY=e.clientY}
function onPointerUp(e){const wasDrag=dragStart?.moved;pointerMap.delete(e.pointerId);if(pointerMap.size<2)pinchStart=null;if(!wasDrag&&dragStart){const p=worldAt(e.clientX,e.clientY);if(p)handleFieldTap(e.clientX,e.clientY,p)}dragStart=null}
canvas.addEventListener('pointerdown',onPointerDown);canvas.addEventListener('pointermove',onPointerMove);canvas.addEventListener('pointerup',onPointerUp);canvas.addEventListener('pointercancel',onPointerUp);canvas.addEventListener('wheel',e=>{zoom=THREE.MathUtils.clamp(zoom+e.deltaY*.018,16,42);positionCamera()},{passive:true});
function handleFieldTap(x,y,p){pointer.x=x/innerWidth*2-1;pointer.y=-(y/innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);const meshes=[];for(const u of units)if(!u.dead)meshes.push(u.mesh);const hits=raycaster.intersectObjects(meshes,true);if(hits.length){const entity=hits[0].object.userData.entity;if(entity){if(entity.side==='ally'&&!attackOrder){selectUnit(entity);notify(`${entity.type==='scout'?'Ranger':'Northwatch guard'} selected`)}else if(selected){selected.target=entity;selected.dest=null;attackOrder=false;document.querySelector('#attackBtn').classList.remove('active');notify('Attack order: engage the hostile company.')}return}}
 if(selected){if(attackOrder){selected.target={kind:'keep',side:'enemy'};selected.dest=null;attackOrder=false;document.querySelector('#attackBtn').classList.remove('active');notify('Company advancing on the Ashen Keep.')}else{selected.target=null;selected.dest={x:THREE.MathUtils.clamp(p.x,-25,25),z:THREE.MathUtils.clamp(p.z,-17,17)};notify('Orders received. Move out.')}}}
function setAllAttack(){attackOrder=!attackOrder;document.querySelector('#attackBtn').classList.toggle('active',attackOrder);if(attackOrder)notify('Tap an enemy or the Ashen Keep to attack.');else notify('Attack order cancelled.')}
document.querySelector('#trainBtn').addEventListener('click',()=>{if(gold<80){notify('Not enough crowns. Hold the pass to earn more.');return}if(supply>=supplyMax){notify('Company at supply limit. Build a watchtower.');return}spawn('ally','guard',-12+Math.random()*1.8,(Math.random()-.5)*2.7);notify('A Northwatch guard joins your company.')});
document.querySelector('#scoutBtn').addEventListener('click',()=>{if(gold<60){notify('Not enough crowns to train a ranger.');return}if(supply>=supplyMax){notify('Company at supply limit. Build a watchtower.');return}spawn('ally','scout',-12+Math.random()*1.8,(Math.random()-.5)*2.7);notify('Ranger recruited — quick and deadly at range.')});
let towerCount=0;const towers=[];
document.querySelector('#towerBtn').addEventListener('click',()=>{if(wood<100){notify('Not enough timber to build a watchtower.');return}wood-=100;towerCount++;supplyMax=Math.min(18,supplyMax+2);const z=towerCount%2?-5:5,x=-10+(towerCount>2?Math.floor((towerCount-1)/2)*2:0);const t=new THREE.Group(),stem=new THREE.Mesh(new THREE.CylinderGeometry(.55,.75,2.1,8),mat('#74634a'));stem.position.y=1.05;stem.castShadow=true;t.add(stem);const deck=new THREE.Mesh(new THREE.BoxGeometry(1.7,.22,1.7),mat('#9a8159'));deck.position.y=2.15;t.add(deck);const roof=new THREE.Mesh(new THREE.ConeGeometry(1.1,1.3,4),mat('#556c61'));roof.position.y=3.12;roof.rotation.y=Math.PI/4;roof.castShadow=true;t.add(roof);t.position.set(x,0,z);scene.add(t);towers.push({mesh:t,cooldown:0});notify('Watchtower raised. Supply increased by 2.')});
