function updateUnit(u,dt){if(u.dead)return;u.cooldown=Math.max(0,u.cooldown-dt);let target=u.target;
 if(target&&target.mesh?.userData?.entity?.dead){target=null;u.target=null}
 if(!target){const near=nearestEnemy(u,u.side==='ally'?5.2:7.5);if(near){target=near;u.target=near}else if(u.side==='ally'&&u.x>8&&u.type==='vanguard'){target={kind:'keep',side:'enemy'};u.target=target}else if(u.side==='enemy'&&Math.abs(u.x+16)<8){target={kind:'keep',side:'home'};u.target=target}}
 let tx=u.x,tz=u.z,attackTarget=null,range=u.range;
 if(target?.kind==='keep'){tx=target.side==='enemy'?12.4:-12.4;tz=0;range=2.15;if(distance(u,{x:tx,z:tz})<=range)attackTarget=target}
 else if(target){tx=target.x;tz=target.z;attackTarget=target}
 else if(u.dest){tx=u.dest.x;tz=u.dest.z;if(distance(u,u.dest)<.42)u.dest=null}
 else if(u.side==='enemy'&&u.type==='raider'){tx=-12.5;tz=u.z;target={kind:'keep',side:'home'};u.target=target}
 const d=Math.hypot(tx-u.x,tz-u.z);let moving=d>.36&&!attackTarget;
 if(moving){const step=Math.min(d,u.speed*dt);u.x+=(tx-u.x)/d*step;u.z+=(tz-u.z)/d*step;u.mesh.rotation.y=Math.atan2(tx-u.x,tz-u.z);u.walk+=dt*9;u.legs[0].rotation.x=Math.sin(u.walk)*.3;u.legs[1].rotation.x=-Math.sin(u.walk)*.3;u.mesh.position.set(u.x,Math.abs(Math.sin(u.walk))*.035,u.z)}else{u.legs[0].rotation.x*=.8;u.legs[1].rotation.x*=.8;u.mesh.position.set(u.x,0,u.z)}
 if(attackTarget&&u.cooldown<=0&&d<=range+.35){u.cooldown=u.attackRate;if(attackTarget.kind==='keep'){if(attackTarget.side==='enemy'){enemyIntegrity=Math.max(0,enemyIntegrity-u.damage*.7);document.querySelector('#enemyHp').style.width=enemyIntegrity+'%';document.querySelector('#enemyHpText').textContent=`${Math.ceil(enemyIntegrity)}% integrity`;if(enemyIntegrity<=0)finish(true)}else{homeIntegrity=Math.max(0,homeIntegrity-u.damage*.8);document.querySelector('#homeHp').style.width=homeIntegrity+'%';if(homeIntegrity<=0)finish(false)}}else damageUnit(attackTarget,u.damage)}
}
